/* Demonstrates the use of pthread_equal() for reliable thread ID comparison */
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>

// Store the thread ID retrieved inside the worker function
pthread_t worker_tid_internal;

void *worker_function(void *arg) {
    // Retrieve and store the thread ID internally
    worker_tid_internal = pthread_self();
    printf("Worker thread running, ID stored: %lu\n", (unsigned long)worker_tid_internal);
    sleep(1);
    return NULL;
}

int main() {
    pthread_t main_tid = pthread_self();
    pthread_t worker_tid_external; // ID retrieved from pthread_create

    printf("Main thread ID: %lu\n", (unsigned long)main_tid);

    // Create the worker thread
    if (pthread_create(&worker_tid_external, NULL, worker_function, NULL) != 0) {
        perror("pthread_create failed");
        return EXIT_FAILURE;
    }

    // Wait for the worker thread to complete
    if (pthread_join(worker_tid_external, NULL) != 0) {
        perror("pthread_join failed");
        return EXIT_FAILURE;
    }

    printf("\n--- Comparison Results using pthread_equal() ---\n");

    // Comparison 1: Compare IDs obtained through different methods (should be equal)
    if (pthread_equal(worker_tid_external, worker_tid_internal)) {
        printf("1. Success: External ID matches Internal ID.\n");
    } else {
        printf("1. Error: IDs for the same thread should match.\n");
    }

    // Comparison 2: Compare two different thread IDs (should be unequal)
    if (pthread_equal(main_tid, worker_tid_internal)) {
        printf("2. Error: Main ID equals Worker ID.\n");
    } else {
        printf("2. Success: Main ID differs from Worker ID.\n");
    }

    // Comparison 3: Compare an ID against itself (always equal)
    if (pthread_equal(main_tid, main_tid)) {
        printf("3. Success: Main ID equals itself.\n");
    } else {
        printf("3. Error: An ID must equal itself.\n");
    }

    return EXIT_SUCCESS;
}
